  "mutants": [
    {
      "bug": "Reset is sampled only on the clock edge instead of acting asynchronously.",
      "edits": [
        {
          "old": "always_ff @(posedge clk or posedge reset) begin",
          "new": "always_ff @(posedge clk) begin"
        }
      ]
    },
